        "status": "supported"
    },
    {
        "root_cause_class": "configuration_change",
        "summary": "No ConfigMap changes detected between rollout and failure, as per referenced_config and rollout_history.",
        "supporting": ["ev-referenced_config", "ev-rollout_history"],
        "contradicting": [],
        "missing": [],
        "status": "supported"
    }
],
"proposal": {
    "capability": "deployment.rollback-to-revision",
    "target": {
        "group": "apps",
        "kind": "Deployment",
        "namespace": "shop",
        "name": "checkout",
        "uid": "uid-deployment-checkout"
    },
    "params": {
        "revision": 1
    },
    "expected_effect": "Revert to revision 1's working image 'example/checkout:2.3.1' and resolve the image pull failure.",
    "rationale": "The new revision's image is unavailable, and the prior revision is healthy. Rolling back is justified as the failure onset occurred after the rollout, and no config changes were detected before the failure.",
    "cited_evidence_ids": ["ev-rollout_history", "ev-pod_states", "ev-target_events", "ev-referenced_config"],
    "cited_predicates": ["rollout_recent", "failure_onset_after_rollout", "prior_revision_was_healthy", "gitops_managed", "config_changed_before_failure"]
}
}
